        "family": "symbolic",
        "params": {"window": 12},
        "channels": [
          {"time_op": "path_efficiency", "feature_op": "mean", "window": 12, "feature_slice": [29, 95], "interaction": "corr", "rhs_slice": [95, 158], "transform": "tanh", "weight": 1.2},
