          {"time_op": "skew", "feature_op": "top_bottom_spread", "window": 5, "feature_slice": [0, 9], "interaction": "ratio", "rhs_slice": [95, 158], "rhs_time_op": "std", "rhs_window": 5, "transform": "tanh", "weight": 1.1},
