        "family": "symbolic",
        "params": {"window": 10},
        "channels": [
          {"time_op": "mean", "feature_op": "corr_half", "window": 10, "feature_slice": [95, 158], "interaction": "lead_lag_corr", "rhs_slice": [9, 29], "rhs_window": 10, "transform": "tanh", "weight": 1.2},
